import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { CalendarDays, ChevronLeft, ChevronRight, ClipboardList, Clock3, Download, FileText, Megaphone, QrCode, Send, Users } from 'lucide-react'
import { QRCodeSVG } from 'qrcode.react'
import { supabase } from '../lib/supabase'
import { friendlyError } from '../components/UserFeedback'
import { useFeedback } from '../components/UserFeedback'
import { ProfilePhotoManager } from '../components/ProfilePhoto'
import { AnnouncementFeed } from '../admin/AnnouncementManagement'

type Profile={id:string;full_name:string;is_active:boolean;profile_photo_path?:string|null}
type Student={id:string;student_id:string;grade_level:string;status:string;section_id:string|null;created_at:string;profiles?:{full_name:string;email:string;phone:string|null}|null;sections?:{name:string}|null;student_private_details?:Record<string,unknown>|null;enrollment_records?:{school_year:string;status:string}[]}
type Row=Record<string,unknown>
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila'}).format(new Date())
const dateLabel=(v:unknown)=>v?new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium'}).format(new Date(String(v))):'—'
const dateTime=(v:unknown)=>v?new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'short'}).format(new Date(String(v))):'—'
const statusColor=(s:string)=>['APPROVED','ACCEPTED','COMPLETED','USED','ENROLLED','active','present'].includes(s)?'bg-emerald-100 text-emerald-800':['REJECTED','EXPIRED','absent'].includes(s)?'bg-rose-100 text-rose-800':['UNDER_REVIEW','IN_REVIEW'].includes(s)?'bg-sky-100 text-sky-800':['CANCELLED'].includes(s)?'bg-slate-100 text-slate-700':'bg-amber-100 text-amber-900'
function Badge({value}:{value:string}){return <span className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide ${statusColor(value)}`}>{value.replaceAll('_',' ')}</span>}
function Card({children,className=''}:{children:React.ReactNode;className?:string}){return <section className={`rounded-3xl border border-[var(--color-border)] bg-white p-5 shadow-sm ${className}`}>{children}</section>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block text-sm font-semibold text-slate-700">{label}{children}</label>}
function Input(props:React.InputHTMLAttributes<HTMLInputElement>){return <input {...props} className={`mt-1 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm font-normal outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-700/10 ${props.className??''}`}/>}
function Textarea(props:React.TextareaHTMLAttributes<HTMLTextAreaElement>){return <textarea {...props} className={`mt-1 w-full rounded-xl border border-slate-200 px-3 py-2.5 text-sm font-normal outline-none focus:border-emerald-700 focus:ring-2 focus:ring-emerald-700/10 ${props.className??''}`}/>}
function Select({children,...props}:React.SelectHTMLAttributes<HTMLSelectElement>){return <select {...props} className={`mt-1 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-normal outline-none focus:border-emerald-700 ${props.className??''}`}>{children}</select>}

export function StudentPortal({profile,onPhotoSaved}:{profile:Profile;onPhotoSaved:(path:string|null)=>void}){
  const { confirmAction } = useFeedback()
  const location=useLocation();const navigate=useNavigate();const qrRef=useRef<SVGSVGElement|null>(null);const [student,setStudent]=useState<Student|null>(null);const [events,setEvents]=useState<Row[]>([]);const [summaries,setSummaries]=useState<Row[]>([]);const [early,setEarly]=useState<Row[]>([]);const [visitors,setVisitors]=useState<Row[]>([]);const [visitorLogs,setVisitorLogs]=useState<Row[]>([]);const [absence,setAbsence]=useState<Row[]>([]);const [corrections,setCorrections]=useState<Row[]>([]);const [notices,setNotices]=useState<Row[]>([]);const [reads,setReads]=useState<Set<string>>(new Set());const [notifications,setNotifications]=useState<Row[]>([]);const [qrToken,setQrToken]=useState('');const [qrBusy,setQrBusy]=useState(false);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [message,setMessage]=useState('');const [search,setSearch]=useState('');const [filterStatus,setFilterStatus]=useState('all');const [requestType,setRequestType]=useState('all');const [requestDate,setRequestDate]=useState('');const [history,setHistory]=useState<Row[]>([]);const [selectedRequest,setSelectedRequest]=useState<Row|null>(null)
  const [month,setMonth]=useState(()=>new Date());const [attendanceFrom,setAttendanceFrom]=useState('');const [attendanceTo,setAttendanceTo]=useState('');const [attendanceMonth,setAttendanceMonth]=useState(()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit'}).format(new Date()));const [attendanceStatus,setAttendanceStatus]=useState('all')
  const [earlyDate,setEarlyDate]=useState('');const [earlyTime,setEarlyTime]=useState('');const [earlyReason,setEarlyReason]=useState('');const [earlyExplanation,setEarlyExplanation]=useState('');const [guardianName,setGuardianName]=useState('');const [guardianContact,setGuardianContact]=useState('')
  const [visitorName,setVisitorName]=useState('');const [visitorRelation,setVisitorRelation]=useState('');const [visitorContact,setVisitorContact]=useState('');const [visitorIdType,setVisitorIdType]=useState('');const [visitorDate,setVisitorDate]=useState('');const [visitorArrival,setVisitorArrival]=useState('');const [visitorDeparture,setVisitorDeparture]=useState('');const [visitorPurpose,setVisitorPurpose]=useState('');const [visitorInfo,setVisitorInfo]=useState('')
  const [absenceDate,setAbsenceDate]=useState('');const [absenceReason,setAbsenceReason]=useState('');const [absenceExplanation,setAbsenceExplanation]=useState('');const [absenceGuardian,setAbsenceGuardian]=useState('');const [absenceContact,setAbsenceContact]=useState('')
  const [correctDate,setCorrectDate]=useState('');const [currentStatus,setCurrentStatus]=useState('');const [requestedStatus,setRequestedStatus]=useState('present');const [correctReason,setCorrectReason]=useState('')

  const refresh=useCallback(async()=>{
    if(!supabase)return
    setLoading(true);setError('')
    const {data:s,error:sErr}=await supabase.from('students').select('id,student_id,grade_level,status,section_id,created_at,profiles(full_name,email,phone),sections(name),student_private_details(birth_date,gender,address,guardian_full_name,guardian_relationship,guardian_contact_number,guardian_address),enrollment_records(school_year,status,date_registered)').eq('profile_id',profile.id).maybeSingle()
    if(sErr||!s){setError(sErr?.message??'No student record is linked to this account.');setLoading(false);return}
    const studentRow={...s,profiles:Array.isArray(s.profiles)?s.profiles[0]??null:s.profiles,sections:Array.isArray(s.sections)?s.sections[0]??null:s.sections,student_private_details:Array.isArray(s.student_private_details)?s.student_private_details[0]??null:s.student_private_details} as Student
    setStudent(studentRow)
    const [ev,summary,e,o,logs,a,c,n,read,not,historyRows]=await Promise.all([
      supabase.from('attendance_events').select('id,event_type,actual_scan_time,verification_result,sync_status').eq('person_type','student').eq('person_id',s.id).order('actual_scan_time',{ascending:false}).limit(1000),
      supabase.from('attendance_daily_summaries').select('id,summary_date,status,entry_time,exit_time').eq('student_id',s.id).order('summary_date',{ascending:false}).limit(1000),
      supabase.from('early_out_requests').select('id,requested_departure,reason,additional_explanation,guardian_name,guardian_contact,status,reviewed_by,reviewer_remarks,approved_at,created_at,updated_at').eq('student_id',s.id).order('created_at',{ascending:false}),
      supabase.from('visitor_requests').select('id,visitor_name,visitor_relationship,contact_number,visitor_id_type,visit_date,expected_arrival_time,expected_departure_time,purpose,additional_info,status,approved_by,reviewer_remarks,created_at,updated_at').eq('student_id',s.id).order('created_at',{ascending:false}),
      supabase.from('visitor_logs').select('id,visitor_request_id,visitor_name,visit_date,actual_departure_time,authorization_status').eq('student_id',s.id).order('visit_date',{ascending:false}),
      supabase.from('absence_notices').select('id,absence_date,reason,explanation,guardian_name,guardian_contact,status,reviewer_remarks,reviewed_at,created_at,updated_at').eq('student_id',s.id).order('created_at',{ascending:false}),
      supabase.from('attendance_correction_requests').select('id,attendance_date,current_status,requested_status,reason,status,reviewer_remarks,reviewed_at,created_at,updated_at').eq('student_id',s.id).order('created_at',{ascending:false}),
      supabase.from('announcements').select('id,title,summary,body,audience,category,priority,status,content_format,published_at,expires_at,target_grade_level,target_section_id,attachments,created_at,updated_at').order('published_at',{ascending:false}).limit(100),
      supabase.from('announcement_reads').select('announcement_id').eq('profile_id',profile.id),
      supabase.from('notifications').select('id,type,payload,is_read,created_at').eq('recipient_id',profile.id).order('created_at',{ascending:false}).limit(100),
      supabase.from('student_request_history').select('id,request_type,request_id,old_status,new_status,remarks,changed_at').eq('student_id',s.id).order('changed_at',{ascending:true}),
    ])
    const firstError=[ev.error,summary.error,e.error,o.error,logs.error,a.error,c.error,n.error,read.error,not.error,historyRows.error].find(Boolean)
    if(firstError)setError(friendlyError(firstError))
    setEvents(ev.data??[]);setSummaries(summary.data??[]);setEarly(e.data??[]);setVisitors(o.data??[]);setVisitorLogs(logs.data??[]);setAbsence(a.data??[]);setCorrections(c.data??[]);setNotices(n.data??[]);setReads(new Set((read.data??[]).map(x=>x.announcement_id)));setNotifications(not.data??[]);setHistory(historyRows.data??[]);setLoading(false)
  },[profile.id])
  useEffect(()=>{void refresh()},[refresh])
  useEffect(()=>{if(!supabase)return;const client=supabase;const channel=client.channel(`student-notifications-${profile.id}`).on('postgres_changes',{event:'*',schema:'public',table:'notifications',filter:`recipient_id=eq.${profile.id}`},()=>void refresh()).subscribe();return()=>{void client.removeChannel(channel)}},[profile.id,refresh])
  const isRead=(id:string)=>reads.has(id)
  const unread=notices.filter(x=>x.status==='published'&&(!x.published_at||new Date(String(x.published_at))<=new Date())&&['all','student'].includes(String(x.audience))&&(!x.expires_at||new Date(String(x.expires_at))>new Date())&&(!x.target_grade_level||String(x.target_grade_level)===student?.grade_level)&&(!x.target_section_id||String(x.target_section_id)===student?.section_id)&&!isRead(String(x.id))).length
  const allRequests=useMemo<Row[]>(()=>[
    ...early.map(x=>({...x,request_type:'Early out',requested_date:x.requested_departure} as Row)),
    ...visitors.map(x=>({...x,request_type:'Visitor permission',requested_date:x.visit_date} as Row)),
    ...absence.map(x=>({...x,request_type:'Absence notice',requested_date:x.absence_date} as Row)),
    ...corrections.map(x=>({...x,request_type:'Attendance correction',requested_date:x.attendance_date} as Row)),
  ].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))),[early,visitors,absence,corrections])
  const pending=allRequests.filter(x=>['PENDING','UNDER_REVIEW'].includes(String(x.status))).length
  const approved=allRequests.filter(x=>['APPROVED','ACCEPTED','COMPLETED','USED'].includes(String(x.status))).length
  const daily=useMemo(()=>{
    const grouped=new Map<string,{date:string;entry:string|null;exit:string|null;status:string;remarks:string}>()
    for(const row of summaries){const date=String(row.summary_date);grouped.set(date,{date,entry:row.entry_time?String(row.entry_time):null,exit:row.exit_time?String(row.exit_time):null,status:String(row.status),remarks:''})}
    for(const event of events){const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila'}).format(new Date(String(event.actual_scan_time)));const old=grouped.get(date)??{date,entry:null,exit:null,status:'present',remarks:''};const type=String(event.event_type);if(['ENTRY','RETURN'].includes(type)&&(!old.entry||String(event.actual_scan_time)<old.entry))old.entry=String(event.actual_scan_time);if(['EXIT','EARLY_OUT','TEMPORARY_EXIT'].includes(type)&&(!old.exit||String(event.actual_scan_time)>old.exit))old.exit=String(event.actual_scan_time);if(type==='EARLY_OUT')old.status='early_departure';if(event.verification_result==='LATE')old.status='late';grouped.set(date,old)}
    return [...grouped.values()].sort((a,b)=>b.date.localeCompare(a.date))
  },[summaries,events])
  const presentDays=daily.filter(x=>['present','late','early_departure'].includes(x.status)).length
  const absentDays=daily.filter(x=>x.status==='absent').length
  const todayRow=daily.find(x=>x.date===today())
  const todayAttendance=todayRow?(todayRow.status==='present'?'Present':titleStatus(todayRow.status)):'No attendance recorded'
  const activitySummary=student?.student_private_details as Record<string,unknown>|null
  const sectionName=student?.sections?.name??'Section not assigned'
  const schoolYear=String(student?.enrollment_records?.[0]?.school_year??'')
  const filteredDaily=daily.filter(x=>(!attendanceFrom||x.date>=attendanceFrom)&&(!attendanceTo||x.date<=attendanceTo)&&(attendanceStatus==='all'||x.status===attendanceStatus))
  const monthDate=new Date(month.getFullYear(),month.getMonth(),1);const firstWeekday=monthDate.getDay();const monthDays=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();const monthKey=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`
  const calendarRows=daily.filter(x=>x.date.startsWith(monthKey));const calendarMap=new Map(calendarRows.map(x=>[Number(x.date.slice(-2)),x]))
  const submit=async(table:string,payload:Record<string,unknown>,clear:()=>void)=>{if(!supabase||!student)return;setMessage('Submitting request…');const {data:submitted,error:submitError}=await supabase.from(table).insert({student_id:student.id,...payload}).select('id').single();if(submitError)setMessage(friendlyError(submitError));else{if(['early_out_requests','visitor_requests'].includes(table)&&submitted?.id)void supabase.functions.invoke('dispatch-push',{body:{request_id:submitted.id}});setMessage('Your request was submitted. You can track updates in My Requests.');clear();await refresh()}}
  const issueQr=async()=>{if(!supabase||qrBusy)return;setQrBusy(true);setError('');try{const {data,error:qrError}=await supabase.rpc('issue_self_qr_credential');if(qrError)setError(friendlyError(qrError));else if(typeof data==='string'){setQrToken(data);setMessage('QR generated. Download it to keep a copy; generating a new QR replaces this one.')}}finally{setQrBusy(false)}}
  const downloadQr=()=>{const svg=qrRef.current;if(!svg||!qrToken)return;try{const serialized=new XMLSerializer().serializeToString(svg);const imageUrl=URL.createObjectURL(new Blob([serialized],{type:'image/svg+xml;charset=utf-8'}));const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');const scale=3;canvas.width=(image.naturalWidth||220)*scale;canvas.height=(image.naturalHeight||220)*scale;const context=canvas.getContext('2d');if(!context){URL.revokeObjectURL(imageUrl);setError('Could not prepare the QR image for download.');return}context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.imageSmoothingEnabled=false;context.drawImage(image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(imageUrl);canvas.toBlob(blob=>{if(!blob){setError('Could not create the QR image file.');return}const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`student-qr-${(student?.student_id??'code').replace(/[^a-z0-9_-]/gi,'-')}.png`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);setMessage('QR image downloaded. Keep it private and show it to the guard when requested.')},'image/png')};image.onerror=()=>{URL.revokeObjectURL(imageUrl);setError('Could not prepare the QR image for download.')};image.src=imageUrl}catch{setError('Could not prepare the QR image for download.')}}
  const markRead=async(id:string)=>{if(!supabase)return;const {error:readError}=await supabase.from('announcement_reads').upsert({profile_id:profile.id,announcement_id:id},{onConflict:'profile_id,announcement_id'});if(readError)setError(friendlyError(readError));else{setReads(old=>new Set(old).add(id));setMessage('Announcement marked as read.')}}
  const markOneNotification=async(id:string)=>{if(!supabase)return;const {error:readError}=await supabase.from('notifications').update({is_read:true}).eq('id',id);if(readError)setError(friendlyError(readError));else setNotifications(old=>old.map(n=>n.id===id?{...n,is_read:true}:n))}
  const markAllNotifications=async()=>{if(!supabase)return;const {error:readError}=await supabase.from('notifications').update({is_read:true}).eq('recipient_id',profile.id).eq('is_read',false);if(readError)setError(friendlyError(readError));else setNotifications(old=>old.map(n=>({...n,is_read:true})))}
  const cancel=async(type:string,id:string)=>{if(!supabase)return;await confirmAction({title:'Cancel this request?',description:'The request will be withdrawn and will no longer be processed.',confirmLabel:'Cancel request',tone:'danger',successMessage:'Request cancelled.',onConfirm:async()=>{const {error:cancelError}=await supabase!.rpc('cancel_student_request',{p_request_type:type,p_request_id:id});if(cancelError)throw cancelError;await refresh()}})}
  const page=location.pathname.replace('/student','')||'/';const go=(path:string)=>navigate(path)
  const greeting=()=>{const hour=Number(new Intl.DateTimeFormat('en',{hour:'2-digit',hourCycle:'h23',timeZone:'Asia/Manila'}).format(new Date()));return hour<12?'Good morning':hour<18?'Good afternoon':'Good evening'}
  const safeAnnouncements=notices.filter(x=>x.status==='published'&&(!x.published_at||new Date(String(x.published_at))<=new Date())&&['all','student'].includes(String(x.audience))&&(!x.expires_at||new Date(String(x.expires_at))>new Date())&&(!x.target_grade_level||String(x.target_grade_level)===student?.grade_level)&&(!x.target_section_id||String(x.target_section_id)===student?.section_id))
  const banner=<>{error&&<p role="alert" className="rounded-xl bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}{message&&<p role="status" className="rounded-xl bg-emerald-50 p-3 text-sm text-emerald-900">{message}</p>}</>
  const infoCard=(label:string,value:unknown)=><div key={label} className="rounded-2xl bg-slate-50 p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 break-words text-sm font-semibold">{String(value??'—')}</p></div>
  const quick=[['/student/attendance','View attendance',CalendarDays],['/student/early-out','Request early out',Clock3],['/student/visitor','Request visitor',Users],['/student/absence','Submit absence notice',FileText],['/student/announcements','View announcements',Megaphone],['/student/requests','View my requests',ClipboardList]] as const

  if(loading)return <div className="space-y-4"><div className="h-24 animate-pulse rounded-3xl bg-white"/><div className="grid gap-3 sm:grid-cols-3">{Array.from({length:6},(_,i)=><div key={i} className="h-24 animate-pulse rounded-2xl bg-white"/>)}</div></div>
  if(!student)return <div>{banner}<Card><h2 className="text-xl font-bold">Student record unavailable</h2><p className="mt-2 text-sm text-slate-500">Ask the school administrator to link an active student record to this account.</p></Card></div>
  return <div className="space-y-5">
    {page==='/'&&<>
      <section className="flex flex-wrap items-center justify-between gap-4 rounded-3xl bg-gradient-to-r from-emerald-900 to-emerald-700 p-6 text-white shadow-lg"><div><p className="text-sm font-semibold text-emerald-100">{greeting()}, {student.profiles?.full_name?.split(' ')[0]??profile.full_name.split(' ')[0]}!</p><h2 className="mt-1 text-2xl font-bold">Welcome back to your student portal</h2><div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-sm text-emerald-100"><span>Student no. {student.student_id}</span><span>Grade {student.grade_level} · {sectionName}</span><span>{schoolYear||'School year on file'}</span><span>{dateLabel(new Date().toISOString())}</span></div></div><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-white/15 text-2xl font-bold ring-1 ring-white/30">{(student.profiles?.full_name??profile.full_name).split(' ').map(x=>x[0]).slice(0,2).join('')}</div></section>
      {banner}<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[['Today',todayAttendance],['Present days',presentDays],['Absences',absentDays],['Pending requests',pending],['Approved requests',approved],['Unread announcements',unread]].map(([label,value])=><div key={String(label)} className="rounded-2xl border bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 truncate text-xl font-bold">{value}</p></div>)}</div>
      <Card><h3 className="font-bold">Quick actions</h3><div className="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{quick.map(([path,label,Icon])=><button key={path} onClick={()=>go(path)} className="flex items-center gap-3 rounded-xl border p-3 text-left text-sm font-semibold hover:border-emerald-300 hover:bg-emerald-50"><Icon className="h-5 w-5 text-emerald-800"/>{label}</button>)}</div></Card>
      <div className="grid gap-5 xl:grid-cols-2"><Card><div className="mb-3 flex items-center justify-between"><h3 className="font-bold">Today’s attendance</h3><button onClick={()=>go('/student/attendance')} className="text-sm font-semibold text-emerald-800">Full history</button></div><div className="grid gap-2 sm:grid-cols-2">{infoCard('Status',todayAttendance)}{infoCard('First arrival',todayRow?.entry?dateTime(todayRow.entry):'No entry scan yet')}{infoCard('Last departure',todayRow?.exit?dateTime(todayRow.exit):'No exit recorded')}{infoCard('Days recorded',daily.length)}</div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-slate-50 p-3"><div><p className="font-semibold">Attendance QR</p><p className="text-xs text-slate-500">Use this secure code at the school gate. Download it to show from your phone or print it.</p></div>{qrToken?<div className="flex items-center gap-3"><QRCodeSVG ref={qrRef} value={qrToken} size={240} level="H" includeMargin className="h-24 w-24 shrink-0"/><button onClick={downloadQr} className="inline-flex items-center gap-2 rounded-xl bg-emerald-800 px-3 py-2 text-xs font-semibold text-white"><Download className="h-4 w-4"/>Download QR</button></div>:<button disabled={qrBusy} onClick={()=>void issueQr()} className="rounded-xl bg-emerald-800 px-3 py-2 text-xs font-semibold text-white disabled:opacity-60"><QrCode className="mr-1 inline h-4 w-4"/>{qrBusy?'Generating…':'Generate QR'}</button>}</div></Card><Card><div className="mb-3 flex items-center justify-between"><h3 className="font-bold">Recent request updates</h3><button onClick={()=>go('/student/requests')} className="text-sm font-semibold text-emerald-800">All requests</button></div>{allRequests.slice(0,4).map(r=><div key={`${r.request_type}-${r.id}`} className="flex items-center justify-between gap-3 border-t py-3 text-sm"><div><p className="font-semibold">{String(r.request_type)}</p><p className="text-xs text-slate-500">{dateLabel(r.requested_date)}</p></div><Badge value={String(r.status)}/></div>)}{!allRequests.length&&<p className="py-5 text-sm text-slate-500">No requests submitted yet.</p>}</Card></div>
      <div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Card><div className="mb-3 flex items-center justify-between"><h3 className="font-bold">Latest announcements</h3><button onClick={()=>go('/student/announcements')} className="text-sm font-semibold text-emerald-800">View all</button></div><AnnouncementFeed items={safeAnnouncements.slice(0,3)}/></Card><Card><h3 className="mb-3 font-bold">Student information</h3><div className="grid gap-2 sm:grid-cols-2">{infoCard('Student number',student.student_id)}{infoCard('Grade level',student.grade_level)}{infoCard('Section',sectionName)}{infoCard('Enrollment status',student.status)}</div><button onClick={()=>go('/student/profile')} className="mt-3 text-sm font-semibold text-emerald-800">View profile →</button></Card></div>
    </>}
    {page==='/attendance'&&<><header><h2 className="text-2xl font-bold">My Attendance</h2><p className="mt-1 text-sm text-slate-500">Attendance shown from actual gate scans and recorded daily summaries.</p></header>{banner}<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[['Recorded days',daily.length],['Present',daily.filter(x=>x.status==='present').length],['Late',daily.filter(x=>x.status==='late').length],['Absent',absentDays],['Excused',daily.filter(x=>x.status==='excused').length],['Attendance rate',daily.length?`${Math.round(presentDays/daily.length*100)}%`:'—']].map(([l,v])=><div key={String(l)} className="rounded-2xl border bg-white p-4"><p className="text-xs text-slate-500">{l}</p><p className="mt-1 text-xl font-bold">{v}</p></div>)}</div><Card><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">Attendance calendar</h3><div className="flex items-center gap-3"><button onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}><ChevronLeft/></button><b>{month.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}</b><button onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}><ChevronRight/></button></div></div><div className="grid grid-cols-7 text-center text-xs font-semibold text-slate-500">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=><span key={x} className="py-2">{x}</span>)}{Array.from({length:firstWeekday},(_,i)=><span key={`empty-${i}`}/>)}{Array.from({length:monthDays},(_,i)=>{const day=i+1;const row=calendarMap.get(day);return <button key={day} onClick={()=>row&&setMessage(`${row.date}: ${titleStatus(row.status)}${row.entry?` · Arrival ${dateTime(row.entry)}`:''}${row.exit?` · Departure ${dateTime(row.exit)}`:''}`)} className={`m-1 aspect-square rounded-xl text-sm ${row?row.status==='present'?'bg-emerald-100 text-emerald-900':row.status==='late'?'bg-amber-100 text-amber-900':row.status==='absent'?'bg-rose-100 text-rose-900':row.status==='excused'?'bg-sky-100 text-sky-900':'bg-slate-100':'hover:bg-slate-50'}`}>{day}</button>})}</div><div className="mt-3 flex flex-wrap gap-3 text-xs text-slate-500">{[['bg-emerald-100','Present'],['bg-amber-100','Late'],['bg-rose-100','Absent'],['bg-sky-100','Excused'],['bg-slate-100','No record']].map(([c,l])=><span key={l} className="inline-flex items-center gap-1"><i className={`h-3 w-3 rounded ${c}`}/>{l}</span>)}</div></Card><Card><div className="mb-4 flex flex-wrap gap-2"><label className="text-xs">From<Input type="date" value={attendanceFrom} onChange={e=>setAttendanceFrom(e.target.value)}/></label><label className="text-xs">To<Input type="date" value={attendanceTo} onChange={e=>setAttendanceTo(e.target.value)}/></label><label className="text-xs">Status<Select value={attendanceStatus} onChange={e=>setAttendanceStatus(e.target.value)}><option value="all">All statuses</option>{['present','late','absent','incomplete','early_departure'].map(s=><option key={s}>{s}</option>)}</Select></label><label className="text-xs">Month<Input type="month" value={attendanceMonth} onChange={e=>{setAttendanceMonth(e.target.value);setAttendanceFrom(e.target.value?`${e.target.value}-01`:'');setAttendanceTo(e.target.value?`${e.target.value}-31`:'')}}/></label></div><AttendanceTable rows={filteredDaily}/></Card><CorrectionForm date={correctDate} setDate={setCorrectDate} current={currentStatus} setCurrent={setCurrentStatus} requested={requestedStatus} setRequested={setRequestedStatus} reason={correctReason} setReason={setCorrectReason} daily={daily} submit={()=>void submit('attendance_correction_requests',{attendance_date:correctDate,current_status:currentStatus,requested_status:requestedStatus,reason:correctReason},()=>{setCorrectDate('');setCurrentStatus('');setCorrectReason('')})}/></>}
    {page==='/academic'&&<><h2 className="text-2xl font-bold">My Academic Information</h2>{banner}<Card><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{infoCard('Student name',student.profiles?.full_name)}{infoCard('Student number',student.student_id)}{infoCard('Grade',student.grade_level)}{infoCard('Section',sectionName)}{infoCard('Current status',student.status)}{infoCard('Current school year',schoolYear||'No enrollment year on file')}</div></Card><Card><h3 className="mb-3 font-bold">Enrollment history</h3><EnrollmentHistory studentId={student.id}/></Card></>}
    {page==='/profile'&&<><h2 className="text-2xl font-bold">My Profile</h2>{banner}<Card><h3 className="mb-3 font-bold">Profile picture</h3><p className="mb-2 text-sm text-slate-500">Add or update the photo shown to school staff when your student QR is checked.</p><ProfilePhotoManager currentPath={profile.profile_photo_path} name={profile.full_name} onSaved={onPhotoSaved}/></Card><Card><h3 className="mb-3 font-bold">Personal information</h3><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{infoCard('Full name',student.profiles?.full_name)}{infoCard('Email',student.profiles?.email)}{infoCard('Contact',student.profiles?.phone)}{infoCard('Date of birth',activitySummary?.birth_date?dateLabel(activitySummary.birth_date):'—')}{infoCard('Gender',activitySummary?.gender)}{infoCard('Address',activitySummary?.address)}</div><p className="mt-4 rounded-xl bg-amber-50 p-3 text-sm text-amber-900">To keep school records accurate, profile edits to legal name, contact, address, or guardian information must be reviewed by the school office. Contact the administrator to request a correction.</p></Card><Card><h3 className="mb-3 font-bold">Guardian and account information</h3><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{infoCard('Guardian',activitySummary?.guardian_full_name)}{infoCard('Relationship',activitySummary?.guardian_relationship)}{infoCard('Guardian contact',activitySummary?.guardian_contact_number)}{infoCard('Account status',profile.is_active?'Active':'Inactive')}{infoCard('Registration date',dateLabel(student.created_at))}</div></Card></>}
    {page==='/early-out'&&<><h2 className="text-2xl font-bold">Early Out Request</h2>{banner}<RequestForm title="Request early dismissal" onSubmit={e=>{e.preventDefault();void submit('early_out_requests',{requested_departure:new Date(`${earlyDate}T${earlyTime}:00+08:00`).toISOString(),reason:earlyReason,additional_explanation:earlyExplanation||null,guardian_name:guardianName,guardian_contact:guardianContact,status:'PENDING'},()=>{setEarlyDate('');setEarlyTime('');setEarlyReason('');setEarlyExplanation('');setGuardianName('');setGuardianContact('')})}}><div className="grid gap-3 sm:grid-cols-2">{infoCard('Student',student.profiles?.full_name)}{infoCard('Student number',student.student_id)}{infoCard('Grade / section',`${student.grade_level} · ${sectionName}`)}<Field label="Departure date"><Input type="date" min={today()} required value={earlyDate} onChange={e=>setEarlyDate(e.target.value)}/></Field><Field label="Preferred departure time"><Input type="time" required value={earlyTime} onChange={e=>setEarlyTime(e.target.value)}/></Field><Field label="Reason"><Input required maxLength={300} value={earlyReason} onChange={e=>setEarlyReason(e.target.value)} placeholder="Reason for leaving"/></Field><Field label="Parent / guardian name"><Input required maxLength={120} value={guardianName} onChange={e=>setGuardianName(e.target.value)}/></Field><Field label="Parent / guardian contact"><Input required maxLength={40} value={guardianContact} onChange={e=>setGuardianContact(e.target.value)}/></Field></div><Field label="Additional explanation"><Textarea rows={3} maxLength={1000} value={earlyExplanation} onChange={e=>setEarlyExplanation(e.target.value)}/></Field><p className="text-xs text-amber-800">Guardian details entered here are not verified consent. The school will review this request before any departure is approved.</p></RequestForm><RequestCards rows={early} onCancel={(id)=>void cancel('early_out',id)}/></>}
    {page==='/visitor'&&<><h2 className="text-2xl font-bold">Visitor Permission</h2>{banner}<RequestForm title="Request a visitor appointment" onSubmit={e=>{e.preventDefault();void submit('visitor_requests',{visitor_name:visitorName,visitor_relationship:visitorRelation,contact_number:visitorContact||null,visitor_id_type:visitorIdType||null,visit_date:visitorDate,expected_arrival_time:visitorArrival,expected_departure_time:visitorDeparture||null,purpose:visitorPurpose,additional_info:visitorInfo||null,status:'PENDING'},()=>{setVisitorName('');setVisitorRelation('');setVisitorContact('');setVisitorIdType('');setVisitorPurpose('');setVisitorInfo('');setVisitorDate('');setVisitorArrival('');setVisitorDeparture('')})}}><div className="grid gap-3 sm:grid-cols-2">{infoCard('Student',student.profiles?.full_name)}{infoCard('Student number',student.student_id)}<Field label="Visitor full name"><Input required value={visitorName} onChange={e=>setVisitorName(e.target.value)}/></Field><Field label="Relationship to student"><Input required value={visitorRelation} onChange={e=>setVisitorRelation(e.target.value)}/></Field><Field label="Contact number"><Input type="tel" value={visitorContact} onChange={e=>setVisitorContact(e.target.value)}/></Field><Field label="ID type (if requested by school)"><Input value={visitorIdType} onChange={e=>setVisitorIdType(e.target.value)} placeholder="e.g. Driver's license"/></Field><Field label="Visit date"><Input required type="date" min={today()} value={visitorDate} onChange={e=>setVisitorDate(e.target.value)}/></Field><Field label="Arrival time"><Input required type="time" value={visitorArrival} onChange={e=>setVisitorArrival(e.target.value)}/></Field><Field label="Expected departure (optional)"><Input type="time" value={visitorDeparture} onChange={e=>setVisitorDeparture(e.target.value)}/></Field><Field label="Purpose"><Input required maxLength={300} value={visitorPurpose} onChange={e=>setVisitorPurpose(e.target.value)}/></Field></div><Field label="Additional information"><Textarea rows={3} maxLength={1000} value={visitorInfo} onChange={e=>setVisitorInfo(e.target.value)}/></Field><p className="text-xs text-amber-800">Approval does not bypass school security. A guard must independently verify visitor identity at entry.</p></RequestForm><Card><h3 className="mb-3 font-bold">Gate entry and exit history</h3><div className="space-y-2">{visitorLogs.map(log=><div key={String(log.id)} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3"><div><p className="font-semibold">{String(log.visitor_name)}</p><p className="text-xs text-slate-500">Entry {dateTime(log.visit_date)} · Exit {log.actual_departure_time?dateTime(log.actual_departure_time):'Not recorded'}</p></div><Badge value={log.actual_departure_time?'COMPLETED':String(log.authorization_status)}/></div>)}{!visitorLogs.length&&<p className="py-4 text-sm text-slate-500">No visitor gate records yet.</p>}</div></Card><RequestCards rows={visitors} onCancel={id=>void cancel('visitor',id)}/></>}
    {page==='/absence'&&<><h2 className="text-2xl font-bold">Absence Notice</h2>{banner}<RequestForm title="Notify the school of an absence" onSubmit={e=>{e.preventDefault();void submit('absence_notices',{absence_date:absenceDate,reason:absenceReason,explanation:absenceExplanation||null,guardian_name:absenceGuardian||null,guardian_contact:absenceContact||null,status:'PENDING'},()=>{setAbsenceDate('');setAbsenceReason('');setAbsenceExplanation('');setAbsenceGuardian('');setAbsenceContact('')})}}><div className="grid gap-3 sm:grid-cols-2"><Field label="Date of absence"><Input required type="date" max={today()} value={absenceDate} onChange={e=>setAbsenceDate(e.target.value)}/></Field><Field label="Reason"><Select value={absenceReason} onChange={e=>setAbsenceReason(e.target.value)} required><option value="">Select reason</option>{['Illness','Family emergency','Personal circumstances','Other'].map(s=><option key={s}>{s}</option>)}</Select></Field><Field label="Parent / guardian name"><Input value={absenceGuardian} onChange={e=>setAbsenceGuardian(e.target.value)}/></Field><Field label="Parent / guardian contact"><Input value={absenceContact} onChange={e=>setAbsenceContact(e.target.value)}/></Field></div><Field label="Explanation"><Textarea rows={4} maxLength={1500} value={absenceExplanation} onChange={e=>setAbsenceExplanation(e.target.value)}/></Field><p className="text-xs text-slate-500">An accepted notice does not change attendance. A reviewer must separately confirm any attendance correction.</p></RequestForm><RequestCards rows={absence} onCancel={id=>void cancel('absence',id)}/></>}
    {page==='/correction'&&<><h2 className="text-2xl font-bold">Attendance Correction</h2>{banner}<CorrectionForm date={correctDate} setDate={setCorrectDate} current={currentStatus} setCurrent={setCurrentStatus} requested={requestedStatus} setRequested={setRequestedStatus} reason={correctReason} setReason={setCorrectReason} daily={daily} submit={()=>void submit('attendance_correction_requests',{attendance_date:correctDate,current_status:currentStatus,requested_status:requestedStatus,reason:correctReason},()=>{setCorrectDate('');setCurrentStatus('');setCorrectReason('')})}/><RequestCards rows={corrections} onCancel={id=>void cancel('attendance_correction',id)}/></>}
    {page==='/announcements'&&<><h2 className="text-2xl font-bold">School Announcements</h2>{banner}<AnnouncementSearch rows={safeAnnouncements} reads={reads} onRead={markRead}/></>}
    {page==='/notifications'&&<><div className="flex items-center justify-between"><h2 className="text-2xl font-bold">Notifications</h2><button onClick={()=>void markAllNotifications()} className="text-sm font-semibold text-emerald-800">Mark all read</button></div>{banner}<div className="space-y-2">{notifications.map(n=><Card key={String(n.id)} className={n.is_read?'':'border-emerald-300 bg-emerald-50'}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{titleStatus(String(n.type))}</p><p className="mt-1 text-sm text-slate-600">{String((n.payload as Record<string,unknown>)?.message??(n.payload as Record<string,unknown>)?.status??'School portal update')}</p><time className="mt-2 block text-xs text-slate-500">{dateTime(n.created_at)}</time></div>{!n.is_read&&<button onClick={()=>void markOneNotification(String(n.id))} className="rounded-lg border px-2 py-1 text-xs">Mark read</button>}</div></Card>)}{!notifications.length&&<Card><p className="text-sm text-slate-500">No notifications yet.</p></Card>}</div></>}
    {page==='/requests'&&<><h2 className="text-2xl font-bold">My Requests</h2>{banner}<Card><div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search requests" className="rounded-xl border px-3 py-2 text-sm"/><Select value={requestType} onChange={e=>setRequestType(e.target.value)}><option value="all">All request types</option>{['Early out','Visitor permission','Absence notice','Attendance correction'].map(x=><option key={x}>{x}</option>)}</Select><Select value={filterStatus} onChange={e=>setFilterStatus(e.target.value)}><option value="all">All statuses</option>{['PENDING','UNDER_REVIEW','APPROVED','ACCEPTED','REJECTED','CANCELLED','EXPIRED','COMPLETED','USED'].map(x=><option key={x}>{x}</option>)}</Select><Input type="date" aria-label="Submitted date filter" value={requestDate} onChange={e=>setRequestDate(e.target.value)}/></div><RequestTable rows={allRequests.filter(x=>(requestType==='all'||x.request_type===requestType)&&(filterStatus==='all'||x.status===filterStatus)&&(!search||`${x.request_type} ${x.reason??x.purpose??''} ${x.id}`.toLowerCase().includes(search.toLowerCase()))&&(!requestDate||String(x.created_at).slice(0,10)>=requestDate))} onCancel={cancel} onView={setSelectedRequest}/></Card></>}
    {selectedRequest&&<RequestDetail request={selectedRequest} history={history.filter(h=>h.request_type===cancelType(String(selectedRequest.request_type))&&h.request_id===selectedRequest.id)} onClose={()=>setSelectedRequest(null)}/>}
  </div>
}

function titleStatus(v:string){return v.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function AttendanceTable({rows}:{rows:{date:string;entry:string|null;exit:string|null;status:string;remarks:string}[]}){return <div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-slate-50 text-slate-500"><tr>{['Date','Time in','Time out','Attendance status','Remarks'].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r.date} className="border-t"><td className="px-3 py-3">{dateLabel(r.date)}</td><td className="px-3 py-3">{r.entry?dateTime(r.entry):'—'}</td><td className="px-3 py-3">{r.exit?dateTime(r.exit):'—'}</td><td className="px-3 py-3"><Badge value={r.status}/></td><td className="px-3 py-3">{r.remarks||'—'}</td></tr>)}{!rows.length&&<tr><td colSpan={5} className="px-3 py-7 text-center text-slate-500">No attendance records for these filters.</td></tr>}</tbody></table></div>}
function RequestForm({title,children,onSubmit}:{title:string;children:React.ReactNode;onSubmit:(e:React.FormEvent<HTMLFormElement>)=>void}){return <Card><form onSubmit={onSubmit} className="space-y-4"><h3 className="font-bold">{title}</h3>{children}<button className="inline-flex items-center gap-2 rounded-xl bg-emerald-800 px-4 py-2.5 text-sm font-semibold text-white"><Send className="h-4 w-4"/>Submit request</button></form></Card>}
function RequestCards({rows,onCancel}:{rows:Row[];onCancel:(id:string)=>void}){return <Card><h3 className="mb-3 font-bold">Request history</h3><div className="space-y-2">{rows.map(r=><div key={String(r.id)} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3"><div><p className="font-semibold">{String(r.reason??r.purpose??r.requested_status??'Request')}</p><p className="text-xs text-slate-500">Submitted {dateLabel(r.created_at)} · Requested {dateLabel(r.requested_departure??r.visit_date??r.absence_date??r.attendance_date)}</p>{Boolean(r.reviewer_remarks)&&<p className="mt-1 text-sm">Review: {String(r.reviewer_remarks)}</p>}</div><div className="flex items-center gap-2"><Badge value={String(r.status)}/>{r.status==='PENDING'&&<button onClick={()=>onCancel(String(r.id))} className="text-xs font-semibold text-rose-700">Cancel</button>}</div></div>)}{!rows.length&&<p className="py-4 text-sm text-slate-500">No requests yet.</p>}</div></Card>}
function RequestTable({rows,onCancel,onView}:{rows:Row[];onCancel:(type:string,id:string)=>void;onView:(row:Row)=>void}){return <div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-slate-50"><tr>{['Type','Submitted','Requested date','Status','Last updated','Actions'].map(x=><th key={x} className="whitespace-nowrap px-3 py-3">{x}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={`${r.request_type}-${r.id}`} className="border-t"><td className="px-3 py-3 font-semibold">{String(r.request_type)}</td><td className="whitespace-nowrap px-3 py-3">{dateLabel(r.created_at)}</td><td className="whitespace-nowrap px-3 py-3">{dateLabel(r.requested_date)}</td><td className="px-3 py-3"><Badge value={String(r.status)}/></td><td className="whitespace-nowrap px-3 py-3">{dateLabel(r.updated_at)}</td><td className="whitespace-nowrap px-3 py-3"><button onClick={()=>onView(r)} className="mr-3 font-semibold text-emerald-800">Details</button>{r.status==='PENDING'&&<button onClick={()=>onCancel(cancelType(String(r.request_type)),String(r.id))} className="font-semibold text-rose-700">Cancel</button>}</td></tr>)}{!rows.length&&<tr><td colSpan={6} className="px-3 py-8 text-center text-slate-500">No matching requests.</td></tr>}</tbody></table></div>}
function cancelType(type:string){return type==='Early out'?'early_out':type==='Visitor permission'?'visitor':type==='Absence notice'?'absence':'attendance_correction'}
function RequestDetail({request,history,onClose}:{request:Row;history:Row[];onClose:()=>void}){
  const fields=['visitor_name','visitor_relationship','contact_number','visitor_id_type','expected_arrival_time','expected_departure_time','additional_info','requested_departure','additional_explanation','guardian_name','guardian_contact','absence_date','explanation','attendance_date','current_status','requested_status']
  return <div className="fixed inset-0 z-[75] flex items-center justify-center bg-slate-950/50 p-4" onClick={onClose}><article role="dialog" aria-modal="true" aria-label="Request details" onClick={e=>e.stopPropagation()} className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-6"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-emerald-800">{String(request.request_type)}</p><h3 className="mt-1 text-xl font-bold">Request details</h3></div><button onClick={onClose} className="rounded-lg border px-3 py-1.5">Close</button></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><Info label="Request ID" value={request.id}/><Info label="Status" value={titleStatus(String(request.status))}/><Info label="Submitted" value={dateTime(request.created_at)}/><Info label="Requested date" value={dateLabel(request.requested_date)}/><Info label="Reason / purpose" value={request.reason??request.purpose??'—'}/><Info label="Reviewer remarks" value={request.reviewer_remarks??'No remarks'}/>{fields.filter(key=>request[key]!==null&&request[key]!==undefined&&request[key]!==''&&!['reason','purpose','attendance_date','absence_date'].includes(key)).map(key=><Info key={key} label={titleStatus(key)} value={key==='requested_departure'?dateTime(request[key]):request[key]}/>)}</div><h4 className="mt-6 font-bold">Request timeline</h4><ol className="mt-3 space-y-3 border-l-2 border-emerald-100 pl-4">{history.map(h=><li key={String(h.id)} className="relative"><span className="absolute -left-[22px] top-1 h-3 w-3 rounded-full bg-emerald-600 ring-4 ring-white"/><p className="font-semibold">{h.old_status?`${titleStatus(String(h.old_status))} → `:''}{titleStatus(String(h.new_status))}</p><p className="text-xs text-slate-500">{dateTime(h.changed_at)}</p>{Boolean(h.remarks)&&<p className="mt-1 text-sm">{String(h.remarks)}</p>}</li>)}{!history.length&&<li className="text-sm text-slate-500">No status history recorded yet.</li>}</ol></article></div>
}
function Info({label,value}:{label:string;value:unknown}){return <div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 break-words text-sm font-semibold">{String(value??'—')}</p></div>}
function CorrectionForm({date,setDate,current,setCurrent,requested,setRequested,reason,setReason,daily,submit}:{date:string;setDate:(v:string)=>void;current:string;setCurrent:(v:string)=>void;requested:string;setRequested:(v:string)=>void;reason:string;setReason:(v:string)=>void;daily:{date:string;status:string}[];submit:()=>void}){return <RequestForm title="Request attendance correction" onSubmit={e=>{e.preventDefault();submit()}}><div className="grid gap-3 sm:grid-cols-2"><Field label="Attendance date"><Select required value={date} onChange={e=>{setDate(e.target.value);setCurrent(daily.find(x=>x.date===e.target.value)?.status??'not recorded')}}><option value="">Select date</option>{daily.map(d=><option key={d.date} value={d.date}>{dateLabel(d.date)} · {d.status}</option>)}</Select></Field><Field label="Current recorded status"><Input readOnly required value={current}/></Field><Field label="Requested correction"><Select value={requested} onChange={e=>setRequested(e.target.value)}>{['present','late','absent','incomplete','early_departure'].map(x=><option key={x}>{x}</option>)}</Select></Field></div><Field label="Reason"><Textarea required rows={3} maxLength={1000} value={reason} onChange={e=>setReason(e.target.value)}/></Field><p className="text-xs text-slate-500">Submitting a request does not change the attendance record. An authorized reviewer must approve any correction.</p></RequestForm>}
function EnrollmentHistory({studentId}:{studentId:string}){const [rows,setRows]=useState<Row[]>([]);useEffect(()=>{if(supabase)void supabase.from('enrollment_records').select('id,school_year,grade_level,status,date_registered,remarks,sections(name)').eq('student_id',studentId).order('date_registered',{ascending:false}).then(({data})=>setRows(data??[]))},[studentId]);return <div className="space-y-2">{rows.map(x=><div key={String(x.id)} className="flex flex-wrap items-center justify-between border-t py-3 text-sm"><span>{String(x.school_year)} · Grade {String(x.grade_level)} · {String((x.sections as {name?:string}|null)?.name??'Unassigned')}</span><Badge value={String(x.status)}/></div>)}{!rows.length&&<p className="text-sm text-slate-500">No enrollment history available.</p>}</div>}
function AnnouncementSearch({rows,reads,onRead}:{rows:Row[];reads:Set<string>;onRead:(id:string)=>void}){const [query,setQuery]=useState('');const [category,setCategory]=useState('all');const filtered=rows.filter(r=>(category==='all'||r.category===category)&&`${r.title} ${r.summary??''} ${r.body}`.toLowerCase().includes(query.toLowerCase()));return <><div className="mb-4 grid gap-2 sm:grid-cols-[1fr_14rem]"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search announcements" className="rounded-xl border px-3 py-2.5"/><select value={category} onChange={e=>setCategory(e.target.value)} className="rounded-xl border px-3 py-2.5"><option value="all">All categories</option>{[...new Set(rows.map(r=>String(r.category)))].map(c=><option key={c}>{c}</option>)}</select></div><div className="grid gap-4 lg:grid-cols-2">{filtered.map(r=><article key={String(r.id)} className="rounded-2xl border bg-white p-4"><AnnouncementFeed items={[r]}/><div className="mt-2 flex items-center justify-between"><Badge value={reads.has(String(r.id))?'Read':'Unread'}/>{!reads.has(String(r.id))&&<button onClick={()=>onRead(String(r.id))} className="text-xs font-semibold text-emerald-800">Mark read</button>}</div></article>)}{!filtered.length&&<p className="text-sm text-slate-500">No announcements found.</p>}</div></>}
